using TMPro;
using UnityEngine;
using UnityEngine.UI;

// GameEvents is unchanged.

public class PlayerHealth : MonoBehaviour
{
    [SerializeField] private int maxHp = 100;
    [SerializeField] private int potionHeal = 30;

    public int MaxHp => maxHp;
    public int CurrentHp { get; private set; }

    // Initialising ITS OWN state in Awake was already correct.
    private void Awake() => CurrentHp = maxHp;

    // One-frame input (GetKeyDown) is read in Update, which runs exactly once per rendered frame.
    // FixedUpdate may run zero, one or several times in a frame.
    private void Update()
    {
        if (Input.GetKeyDown(KeyCode.Q)) ChangeHp(potionHeal);
    }

    public void TakeDamage(int amount) => ChangeHp(-amount);

    private void ChangeHp(int delta)
    {
        CurrentHp = Mathf.Clamp(CurrentHp + delta, 0, maxHp);
        GameEvents.RaisePlayerHealthChanged(CurrentHp, maxHp);
    }
}

public class HealthBarHUD : MonoBehaviour
{
    [SerializeField] private PlayerHealth player;
    [SerializeField] private Slider slider;
    [SerializeField] private TMP_Text label;
    [SerializeField] private GameObject lowHpWarning;

    private bool _started;

    // Subscribe/unsubscribe as a symmetric pair: OnEnable <-> OnDisable.
    private void OnEnable()
    {
        GameEvents.PlayerHealthChanged += Refresh;

        // Events raised while the HUD was hidden were missed, so resync on re-enable.
        // OnEnable is only guaranteed to run after Awake of the SAME object, so the very first
        // OnEnable must not rely on PlayerHealth.Awake having run: skip it and let Start do the first sync.
        if (_started) Refresh(player.CurrentHp, player.MaxHp);
    }

    // Start runs after every Awake of the objects that were active at scene load,
    // so reading another object's state is safe here.
    private void Start()
    {
        _started = true;
        Refresh(player.CurrentHp, player.MaxHp);
    }

    // Called on SetActive(false), on enabled = false, and also when the object
    // is destroyed or the scene is unloaded.
    private void OnDisable() => GameEvents.PlayerHealthChanged -= Refresh;

    private void Refresh(int current, int max)
    {
        slider.value = (float)current / max;
        label.text = current + " / " + max;
        lowHpWarning.SetActive(current * 10 <= max * 3);
    }
}

