// ===== BattleCore.cs : plain C#, no UnityEngine reference (unit-testable) =====
using System;

public interface IRandomSource { float NextValue(); } // 0..1
public interface IBattleAudio { void PlayHit(bool critical); }
public interface IPlayerHud { void ShowHp(int hp); }
public interface IPlayerDamageable { void TakeHit(int attack, int defense); }
public interface IEnemySpawner { int AliveCount { get; } void SpawnWave(int count); }
public interface IProgressStore { int LoadKillCount(); void SaveKillCount(int killCount); }

public readonly struct DamageResult
{
    public readonly int Amount;
    public readonly bool IsCritical;

    public DamageResult(int amount, bool isCritical)
    {
        Amount = amount;
        IsCritical = isCritical;
    }
}

// Pure rule: no sound, no UI, no static Random.
public sealed class DamageCalculator
{
    private readonly IRandomSource _random;

    public DamageCalculator(IRandomSource random)
    {
        _random = random ?? throw new ArgumentNullException(nameof(random));
    }

    public DamageResult Calculate(int attack, int defense, float critChance)
    {
        bool critical = _random.NextValue() < critChance;
        int amount = Math.Max(1, attack - defense);
        if (critical) amount *= 2;
        return new DamageResult(amount, critical);
    }
}

// Player HP flow: asks the calculator, then tells audio and HUD through interfaces.
public sealed class PlayerCombat : IPlayerDamageable
{
    private const float EnemyCritChance = 0.1f;

    private readonly DamageCalculator _calculator;
    private readonly IPlayerHud _hud;
    private readonly IBattleAudio _audio;

    public int Hp { get; private set; }
    public event Action Died;

    public PlayerCombat(DamageCalculator calculator, IPlayerHud hud, IBattleAudio audio, int startHp)
    {
        _calculator = calculator ?? throw new ArgumentNullException(nameof(calculator));
        _hud = hud ?? throw new ArgumentNullException(nameof(hud));
        _audio = audio ?? throw new ArgumentNullException(nameof(audio));
        Hp = startHp;
    }

    public void TakeHit(int attack, int defense)
    {
        DamageResult result = _calculator.Calculate(attack, defense, EnemyCritChance);
        Hp = Math.Max(0, Hp - result.Amount);
        _audio.PlayHit(result.IsCritical);
        _hud.ShowHp(Hp);
        if (Hp == 0) Died?.Invoke();
    }
}

// Kill count, saving and "spawn the next wave when the field is empty".
public sealed class WaveDirector
{
    private readonly IEnemySpawner _spawner;
    private readonly IProgressStore _store;
    private readonly int _waveSize;

    public int KillCount { get; private set; }

    public WaveDirector(IEnemySpawner spawner, IProgressStore store, int waveSize)
    {
        _spawner = spawner ?? throw new ArgumentNullException(nameof(spawner));
        _store = store ?? throw new ArgumentNullException(nameof(store));
        _waveSize = waveSize;
        KillCount = _store.LoadKillCount();
    }

    public void StartBattle() => _spawner.SpawnWave(_waveSize);

    public void OnEnemyKilled()
    {
        KillCount++;
        SaveProgress();
        if (_spawner.AliveCount == 0) _spawner.SpawnWave(_waveSize);
    }

    public void SaveProgress() => _store.SaveKillCount(KillCount);
}

// ===== BattleUnity.cs : thin Unity adapters (split into one file per MonoBehaviour in a real project) =====
using System;
using System.Collections.Generic;
using TMPro;
using UnityEngine;

public sealed class UnityRandomSource : IRandomSource
{
    public float NextValue() => UnityEngine.Random.value;
}

public sealed class PlayerPrefsProgressStore : IProgressStore
{
    private const string KillsKey = "kills";

    public int LoadKillCount() => PlayerPrefs.GetInt(KillsKey, 0);

    public void SaveKillCount(int killCount)
    {
        PlayerPrefs.SetInt(KillsKey, killCount);
        PlayerPrefs.Save();
    }
}

public sealed class BattleAudio : MonoBehaviour, IBattleAudio
{
    [SerializeField] private AudioSource sfx;
    [SerializeField] private AudioClip hitClip;
    [SerializeField] private AudioClip critClip;

    public void PlayHit(bool critical) => sfx.PlayOneShot(critical ? critClip : hitClip);
}

public sealed class PlayerHudView : MonoBehaviour, IPlayerHud
{
    [SerializeField] private TMP_Text hpLabel;

    public void ShowHp(int hp) => hpLabel.text = "HP " + hp;
}

public sealed class Enemy : MonoBehaviour
{
    [SerializeField] private int attack = 12;

    private IPlayerDamageable _player;

    public event Action<Enemy> Died;

    // Method injection: MonoBehaviours cannot receive constructor arguments.
    public void Construct(IPlayerDamageable player) => _player = player;

    private void OnCollisionEnter(Collision collision)
    {
        if (collision.gameObject.CompareTag("Player"))
            _player.TakeHit(attack, 3);
    }

    public void Die() => Died?.Invoke(this);
}

public sealed class EnemySpawner : MonoBehaviour, IEnemySpawner
{
    [SerializeField] private Enemy enemyPrefab;
    [SerializeField] private Transform[] spawnPoints;

    private readonly List<Enemy> _alive = new List<Enemy>();
    private IPlayerDamageable _player;

    public event Action EnemyKilled;
    public int AliveCount => _alive.Count;

    public void Construct(IPlayerDamageable player) => _player = player;

    public void SpawnWave(int count)
    {
        for (int i = 0; i < count; i++)
        {
            Transform point = spawnPoints[i % spawnPoints.Length];
            Enemy enemy = Instantiate(enemyPrefab, point.position, point.rotation);
            enemy.Construct(_player); // the spawner is the only place that knows how to build an Enemy
            enemy.Died += HandleEnemyDied;
            _alive.Add(enemy);
        }
    }

    private void HandleEnemyDied(Enemy enemy)
    {
        enemy.Died -= HandleEnemyDied;
        _alive.Remove(enemy);
        Destroy(enemy.gameObject);
        EnemyKilled?.Invoke();
    }
}

// Composition root: the ONLY place that knows the concrete types and wires them together.
public sealed class BattleInstaller : MonoBehaviour
{
    [SerializeField] private PlayerHudView hudView;
    [SerializeField] private BattleAudio battleAudio;
    [SerializeField] private EnemySpawner spawner;
    [SerializeField] private int playerStartHp = 100;
    [SerializeField] private int waveSize = 3;

    private PlayerCombat _player;
    private WaveDirector _waves;

    private void Awake()
    {
        // An unassigned Inspector reference can be a "fake null" object in the Editor, which a plain C#
        // null check (?? / is null) does not catch, so fail fast here with Unity's == operator.
        if (hudView == null || battleAudio == null || spawner == null)
            throw new InvalidOperationException("BattleInstaller: assign hudView, battleAudio and spawner in the Inspector.");

        var calculator = new DamageCalculator(new UnityRandomSource());
        _player = new PlayerCombat(calculator, hudView, battleAudio, playerStartHp);
        _waves = new WaveDirector(spawner, new PlayerPrefsProgressStore(), waveSize);

        spawner.Construct(_player);
        _player.Died += _waves.SaveProgress;
        spawner.EnemyKilled += _waves.OnEnemyKilled;
    }

    // Gameplay starts in Start, after every Awake (and therefore all wiring) has finished.
    private void Start() => _waves.StartBattle();

    private void OnDestroy()
    {
        if (_player == null || _waves == null) return; // Awake failed before wiring

        _player.Died -= _waves.SaveProgress;
        spawner.EnemyKilled -= _waves.OnEnemyKilled;
    }
}

// ===== DamageCalculatorTests.cs : EditMode test (NUnit / Unity Test Framework), no scene, no Play mode =====
using NUnit.Framework;

public sealed class FixedRandom : IRandomSource
{
    private readonly float _value;
    public FixedRandom(float value) { _value = value; }
    public float NextValue() => _value;
}

public class DamageCalculatorTests
{
    [Test]
    public void Critical_DoublesDamage()
    {
        var calculator = new DamageCalculator(new FixedRandom(0.0f));
        DamageResult result = calculator.Calculate(10, 4, 0.5f);
        Assert.IsTrue(result.IsCritical);
        Assert.AreEqual(12, result.Amount);
    }

    [Test]
    public void Damage_IsAtLeastOne_WhenDefenseExceedsAttack()
    {
        var calculator = new DamageCalculator(new FixedRandom(0.99f));
        DamageResult result = calculator.Calculate(3, 50, 0.5f);
        Assert.IsFalse(result.IsCritical);
        Assert.AreEqual(1, result.Amount);
    }
}

