// ---- Answer key ----
// Q1 (saved into the asset?)
//   (a) O  public int
//   (b) X  private without [SerializeField]
//   (c) O  private, but has [SerializeField]
//   (d) X  static
//   (e) X  const
//   (f) X  readonly
//   (g) X  auto-property, not a field (its generated field is serialized during hot reloading only)
//   (h) O  the explicit backing field 'gold' is serialized; the property 'Gold' just reads it
//   (i) O  List<T> of a [Serializable] custom class
//   (j) X  Buff has no [Serializable]
//   (k) X  dictionaries are not supported
//   (l) X  jagged arrays are not supported
//   (m) X  [NonSerialized] (also not shown in the Inspector)
//   (n) O  [HideInInspector] only hides the field; it is still serialized
//   (o) O  a UnityEngine.Object-derived type is serialized as a reference
//
// Q2 (1) No. Inline serialization turns them into separate objects with identical data.
//    (2) No. Inline serialization cannot represent null; null is replaced with an inline
//        object that has unassigned fields.
//
// Q3 (1) One. All 50 instances reference the same asset.
//    (2) No. In a standalone Player you can only read saved data from ScriptableObject assets.
//    (3) Wrap the nested type in a class or struct, or implement ISerializationCallbackReceiver.

// ---- The same data, written so that every authored value is actually saved ----
using System;
using System.Collections.Generic;
using UnityEngine;

[Serializable]
public class DropEntry
{
    public string itemId;
    public float chance;
}

[Serializable]                       // (j) now meets the custom-class rule
public class Buff
{
    public string id;
    public float duration;
}

[Serializable]
public struct ResistanceEntry        // (k) one serializable row per dictionary entry
{
    public string element;
    public int percent;
}

[CreateAssetMenu(menuName = "Game/Monster Data")]
public class MonsterData : ScriptableObject, ISerializationCallbackReceiver
{
    public const int MaxLevel = 60;                          // a rule in code, not authored data

    [SerializeField] private int maxHp = 100;
    [SerializeField] private float moveSpeed = 3f;           // (b)
    [SerializeField] private float attackRange = 1.5f;
    [SerializeField] private int level = 1;                  // (g) explicit backing field
    [SerializeField] private int gold = 10;
    [SerializeField] private List<DropEntry> drops = new List<DropEntry>();
    [SerializeField] private Buff startBuff = new Buff();
    [SerializeField] private List<ResistanceEntry> resistanceEntries = new List<ResistanceEntry>();
    [SerializeField] private MonsterData evolvesInto;
    [HideInInspector, SerializeField] private int balanceRevision = 7;

    // Rebuilt from resistanceEntries after every load; never serialized itself.
    private Dictionary<string, int> _resistances = new Dictionary<string, int>();

    public int MaxHp => maxHp;
    public float MoveSpeed => moveSpeed;
    public float AttackRange => attackRange;
    public int Level => level;
    public int Gold => gold;
    public IReadOnlyList<DropEntry> Drops => drops;
    public Buff StartBuff => startBuff;
    public MonsterData EvolvesInto => evolvesInto;
    public int BalanceRevision => balanceRevision;

    public int GetResistance(string element)
    {
        return _resistances.TryGetValue(element, out int percent) ? percent : 0;
    }

    // The list is the authored data, so there is nothing to convert before saving.
    public void OnBeforeSerialize() { }

    public void OnAfterDeserialize()
    {
        _resistances = new Dictionary<string, int>();
        for (int i = 0; i < resistanceEntries.Count; i++)
            _resistances[resistanceEntries[i].element] = resistanceEntries[i].percent;
    }
}

