    {
        try { a(); return false; }
        catch (T) { return true; }
    }

    // 뷰에 마지막으로 전달된 내용과 프레젠터 상태가 기대와 같으면 null.
    static string Check(string when, __FakeView v, InventoryPresenter p, string labels, int index, string detail)
    {
        string got = string.Join("|", v.Labels);
        if (got != labels) return when + ": 슬롯 라벨 기대 [" + labels + "], 결과 [" + got + "]";
        if (v.Index != index) return when + ": ShowSelection index 기대 " + index + ", 결과 " + v.Index;
        if (v.Detail != detail) return when + ": ShowSelection detail 기대 \"" + detail + "\", 결과 \"" + v.Detail + "\"";
        if (p.SelectedIndex != index) return when + ": SelectedIndex 기대 " + index + ", 결과 " + p.SelectedIndex;
        return null;
    }

    static string Calls(string when, __FakeView v, int slots, int selection)
    {
        if (v.SlotsCalls != slots) return when + ": ShowSlots 호출 수 기대 " + slots + ", 결과 " + v.SlotsCalls;
        if (v.SelectionCalls != selection) return when + ": ShowSelection 호출 수 기대 " + selection + ", 결과 " + v.SelectionCalls;
        return null;
    }

    static InventoryModel Model3()
    {
