            if (e != null) return e;
            e = Calls("생성 직후", v, 1, 1);
            if (e != null) return e;
            var v2 = new __FakeView();
            var p2 = new InventoryPresenter(new InventoryModel(), v2);
            return Check("빈 인벤토리", v2, p2, "", -1, "");
        });
