// One per slot widget. The panel owns 20 of these and rebinds them on every refresh.
public class SlotView : MonoBehaviour
{
    [SerializeField] private Button button;
    [SerializeField] private TMP_Text label;

    private PlayerInventory _inventory;
    private int _index = -1;

    // Registered once for the lifetime of the widget. Rebinding only changes the data below.
    private void Awake()
    {
        button.onClick.AddListener(OnClicked);
    }

    public void Bind(PlayerInventory inventory, int index)
    {
        _inventory = inventory;
        _index = index;
        label.text = inventory.GetName(index) + " x" + inventory.GetCount(index);
    }

    private void OnClicked()
    {
        if (_inventory != null && _index >= 0)
            _inventory.Use(_index);
    }
}

// The panel GameObject is toggled with SetActive when the player presses I.
public class InventoryPanel : MonoBehaviour
{
    [SerializeField] private PlayerInventory inventory;
    [SerializeField] private SlotView[] slots;        // 20 widgets
    [SerializeField] private Button[] tabButtons;     // 3 buttons
    [SerializeField] private GameObject[] tabPages;   // 3 pages

    private void Awake()
    {
        for (int i = 0; i < tabButtons.Length; i++)
        {
            int tab = i;   // declared inside the loop body: a new variable for every iteration
            tabButtons[i].onClick.AddListener(() => ShowTab(tab));
        }
    }

    private void OnEnable()
    {
        inventory.Changed += Refresh;
        Refresh();   // catch up on changes that happened while the panel was closed
    }

    private void OnDisable()
    {
        inventory.Changed -= Refresh;
    }

    private void ShowTab(int tab)
    {
        for (int p = 0; p < tabPages.Length; p++)
            tabPages[p].SetActive(p == tab);
    }

    private void Refresh()
    {
        for (int i = 0; i < slots.Length; i++)
        {
            bool used = i < inventory.Count;
            slots[i].gameObject.SetActive(used);
            if (used) slots[i].Bind(inventory, i);
        }
    }
}

