using UnityEngine;

// On every enemy (CapsuleCollider + Rigidbody with Is Kinematic off).
[RequireComponent(typeof(Rigidbody))]
public class Knockback : MonoBehaviour
{
    // Newton-seconds. With ForceMode.Impulse the velocity change is impulse / mass.
    [SerializeField] private float impulse = 6f;

    private Rigidbody _rb;

    private void Awake()
    {
        _rb = GetComponent<Rigidbody>();
    }

    // Called by the projectile that hit this enemy.
    public void Apply(Vector3 direction)
    {
        // FIX 1: a body the physics engine simulates is moved through the Rigidbody, not the Transform.
        // The impulse is accumulated now and applied during the next simulation run,
        // so walls and other colliders take part in the resulting motion.
        _rb.AddForce(direction.normalized * impulse, ForceMode.Impulse);
    }
}

// On every enemy.
public class EnemySight : MonoBehaviour
{
    [SerializeField] private Transform eye;
    [SerializeField] private float viewDistance = 15f;

    private int _wallMask;

    private void Awake()
    {
        // FIX 2: Physics.Raycast takes a bit mask. NameToLayer returns the layer index (9);
        // GetMask returns the mask with that layer's bit set (1 << 9 = 512).
        _wallMask = LayerMask.GetMask("Wall");
    }

    public bool CanSee(Transform target)
    {
        Vector3 toTarget = target.position - eye.position;
        float distance = toTarget.magnitude;
        if (distance > viewDistance) return false;
        if (distance < 0.01f) return true;

        bool blocked = Physics.Raycast(eye.position, toTarget / distance, distance, _wallMask);
        return !blocked;
    }
}

// On the patrol drone (SphereCollider with Is Trigger off).
// FIX 3: the drone now has a Rigidbody, so it is no longer a static collider.
// RequireComponent adds the Rigidbody only when this script is added to a GameObject. The drone that is
// already in the scene does not get one automatically: add a Rigidbody to it in the Inspector.
[RequireComponent(typeof(Rigidbody))]
public class PatrolDrone : MonoBehaviour
{
    [SerializeField] private Transform[] waypoints;
    [SerializeField] private float speed = 3f;

    private Rigidbody _rb;
    private int _next;

    private void Awake()
    {
        _rb = GetComponent<Rigidbody>();
        _rb.isKinematic = true;     // scripted path: physics forces must not move it
    }

    private void FixedUpdate()
    {
        Vector3 target = waypoints[_next].position;
        Vector3 next = Vector3.MoveTowards(_rb.position, target, speed * Time.fixedDeltaTime);
        _rb.MovePosition(next);
        if (next == target) _next = (_next + 1) % waypoints.Length;
    }
}

// On the alarm zone (BoxCollider with Is Trigger on, no Rigidbody: a static trigger collider).
// Unchanged: a kinematic collider entering a static trigger collider sends trigger messages.
public class AlarmZone : MonoBehaviour
{
    public int AlarmCount { get; private set; }

    private void OnTriggerEnter(Collider other)
    {
        if (other.GetComponent<PatrolDrone>() != null || other.CompareTag("Player"))
            AlarmCount++;
    }
}

