public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string Expect(string what, string expected, string got)
    {
        return expected == got ? null : what + ": 기대 \"" + expected + "\", 결과 \"" + got + "\"";
    }

    sealed class Probe : System.IDisposable
    {
        readonly System.Text.StringBuilder _log; readonly string _name;
        public int Calls;
        public Probe(System.Text.StringBuilder log, string name) { _log = log; _name = name; }
        public void Dispose() { Calls++; _log.Append(_name); }
    }

    public static void Main()
    {
        Run("publish-order-and-count", () =>
        {
            var ch = new EventChannel<int>();
            var log = new System.Text.StringBuilder();
            ch.Publish(0);
            if (ch.SubscriberCount != 0) return "빈 채널의 SubscriberCount 기대 0, 결과 " + ch.SubscriberCount;
            ch.Subscribe(v => log.Append("A" + v));
            ch.Subscribe(v => log.Append("B" + v));
            ch.Subscribe(v => log.Append("C" + v));
            ch.Publish(1); ch.Publish(2);
            if (ch.SubscriberCount != 3) return "구독 3개 뒤 SubscriberCount 기대 3, 결과 " + ch.SubscriberCount;
            return Expect("A,B,C 구독 후 Publish(1), Publish(2)", "A1B1C1A2B2C2", log.ToString());
        });
        Run("token-dispose-idempotent", () =>
        {
            var ch = new EventChannel<int>();
            var log = new System.Text.StringBuilder();
            System.Action<int> same = v => log.Append("S");
            System.IDisposable first = ch.Subscribe(same);
            ch.Subscribe(v => log.Append("x"));
            ch.Subscribe(same);
            first.Dispose(); first.Dispose(); first.Dispose();
            if (ch.SubscriberCount != 2) return "같은 핸들러를 두 번 구독하고 첫 토큰을 3번 Dispose: SubscriberCount 기대 2, 결과 " + ch.SubscriberCount;
            ch.Publish(0);
            return Expect("첫 토큰만 해지한 뒤 Publish", "xS", log.ToString());
        });
        Run("bag-ends-scene-subscriptions", () =>
        {
            var hp = new EventChannel<int>();
            var chat = new EventChannel<string>();
            var log = new System.Text.StringBuilder();
            var sceneBag = new SubscriptionBag();
            hp.Subscribe(v => log.Append("[global hp" + v + "]"));
            sceneBag.Add(hp.Subscribe(v => log.Append("[hud hp" + v + "]")));
            sceneBag.Add(chat.Subscribe(s => log.Append("[hud chat " + s + "]")));
            if (sceneBag.Count != 2 || sceneBag.IsDisposed) return "Add 2회 뒤 Count 기대 2 / IsDisposed 기대 False, 결과 " + sceneBag.Count + " / " + sceneBag.IsDisposed;
            hp.Publish(1); chat.Publish("hi");
            sceneBag.Dispose(); sceneBag.Dispose();
            if (!sceneBag.IsDisposed || sceneBag.Count != 0) return "Dispose 뒤 IsDisposed 기대 True / Count 기대 0, 결과 " + sceneBag.IsDisposed + " / " + sceneBag.Count;
            hp.Publish(2); chat.Publish("bye");
            if (hp.SubscriberCount != 1 || chat.SubscriberCount != 0) return "가방 Dispose 뒤 SubscriberCount 기대 1 / 0, 결과 " + hp.SubscriberCount + " / " + chat.SubscriberCount;
            return Expect("가방 Dispose 전후의 호출 로그", "[global hp1][hud hp1][hud chat hi][global hp2]", log.ToString());
        });
        Run("bag-dispose-order-and-late-add", () =>
        {
            var log = new System.Text.StringBuilder();
            var bag = new SubscriptionBag();
            var a = new Probe(log, "a"); var b = new Probe(log, "b"); var c = new Probe(log, "c");
            bag.Add(a); bag.Add(b);
            bag.Dispose(); bag.Dispose();
            string e = Expect("Add(a), Add(b) 뒤 Dispose 2회의 해지 로그", "ab", log.ToString());
            if (e != null) return e;
            bag.Add(c);
            if (c.Calls != 1) return "Dispose 된 가방에 Add 한 구독은 즉시 Dispose 되어야 함: Dispose 호출 수 기대 1, 결과 " + c.Calls;
            if (bag.Count != 0) return "Dispose 된 가방에 Add 한 뒤 Count 기대 0, 결과 " + bag.Count;
            return null;
        });
        Run("changes-during-publish", () =>
        {
            var ch = new EventChannel<int>();
            var log = new System.Text.StringBuilder();
            System.IDisposable tokA = null, tokC = null;
            tokA = ch.Subscribe(v => { log.Append("A"); tokA.Dispose(); tokC.Dispose(); });
            ch.Subscribe(v => log.Append("B"));
            tokC = ch.Subscribe(v => log.Append("C"));
            ch.Subscribe(v => { log.Append("D"); if (ch.SubscriberCount != 2) log.Append("(count=" + ch.SubscriberCount + ")"); });
            ch.Publish(0);
            log.Append("|");
            ch.Publish(0);
            string e = Expect("A 가 자신과 C 를 해지: 첫 Publish | 둘째 Publish", "ABD|BD", log.ToString());
            if (e != null) return e;
            ch = new EventChannel<int>();
            log = new System.Text.StringBuilder();
            bool added = false;
            ch.Subscribe(v => { log.Append("A"); if (!added) { added = true; ch.Subscribe(w => log.Append("N")); } });
            ch.Subscribe(v => log.Append("B"));
            ch.Publish(0);
            log.Append("|");
            ch.Publish(0);
            return Expect("A 가 Publish 도중 N 을 구독: 첫 Publish | 둘째 Publish", "AB|ABN", log.ToString());
        });
        Run("bag-disposed-during-publish", () =>
        {
            var ch = new EventChannel<string>();
            var log = new System.Text.StringBuilder();
            var sceneBag = new SubscriptionBag();
            sceneBag.Add(ch.Subscribe(s => log.Append("[hud1]")));
            ch.Subscribe(s => { log.Append("[loader]"); if (s == "unload") sceneBag.Dispose(); });
            sceneBag.Add(ch.Subscribe(s => log.Append("[hud2]")));
            ch.Subscribe(s => log.Append("[audio]"));
            ch.Publish("unload");
            log.Append("|");
            ch.Publish("next");
            if (ch.SubscriberCount != 2) return "SubscriberCount 기대 2, 결과 " + ch.SubscriberCount;
            return Expect("loader 가 Publish 도중 씬 가방을 Dispose", "[hud1][loader][audio]|[loader][audio]", log.ToString());
        });
        Run("nested-publish", () =>
        {
            var ch = new EventChannel<int>();
            var log = new System.Text.StringBuilder();
            System.IDisposable tokB = null;
            ch.Subscribe(v => { log.Append("A" + v); if (v == 1) { tokB.Dispose(); ch.Publish(2); } });
            tokB = ch.Subscribe(v => log.Append("B" + v));
            ch.Subscribe(v => log.Append("C" + v));
            ch.Publish(1);
            log.Append("|");
            ch.Publish(3);
            string e = Expect("A 가 B 를 해지하고 Publish(2) 를 중첩 호출", "A1A2C2C1|A3C3", log.ToString());
            if (e != null) return e;
            ch = new EventChannel<int>();
            log = new System.Text.StringBuilder();
            System.IDisposable tokP = null, tokQ = null;
            tokP = ch.Subscribe(v => log.Append("P" + v));
            tokQ = ch.Subscribe(v => log.Append("Q" + v));
            ch.Subscribe(v => { log.Append("R" + v); if (v == 1) { tokP.Dispose(); tokQ.Dispose(); ch.Publish(2); } });
            ch.Subscribe(v => log.Append("S" + v));
            ch.Publish(1);
            log.Append("|");
            ch.Publish(3);
            return Expect("P,Q,R,S 구독 중 R 이 이미 호출된 P 와 Q 를 해지하고 Publish(2) 를 중첩 호출", "P1Q1R1R2S2S1|R3S3", log.ToString());
        });
        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(20261122);
            for (int round = 0; round < 60; round++)
            {
                var ch = new EventChannel<int>();
                var log = new System.Text.StringBuilder();
                var expected = new System.Text.StringBuilder();
                var tokens = new System.Collections.Generic.List<System.IDisposable>();
                var alive = new System.Collections.Generic.List<bool>();
                var bag = new SubscriptionBag();
                var inBag = new System.Collections.Generic.List<bool>();
                for (int step = 0; step < 80; step++)
                {
                    int op = rng.Next(10);
                    if (op < 4)
                    {
                        int id = tokens.Count;
                        System.IDisposable t = ch.Subscribe(v => log.Append(id).Append(','));
                        bool toBag = rng.Next(3) == 0;
                        bool bagWasDisposed = bag.IsDisposed;
                        if (toBag) bag.Add(t);
                        tokens.Add(t); alive.Add(!(toBag && bagWasDisposed)); inBag.Add(toBag);
                    }
                    else if (op < 6 && tokens.Count > 0)
                    {
                        int id = rng.Next(tokens.Count);
                        tokens[id].Dispose(); alive[id] = false;
                    }
                    else if (op == 6 && rng.Next(4) == 0)
                    {
                        bag.Dispose();
                        for (int i = 0; i < alive.Count; i++) if (inBag[i]) alive[i] = false;
                    }
                    else
                    {
                        ch.Publish(0); log.Append(';');
                        for (int i = 0; i < alive.Count; i++) if (alive[i]) expected.Append(i).Append(',');
                        expected.Append(';');
                    }
                    int count = 0;
                    for (int i = 0; i < alive.Count; i++) if (alive[i]) count++;
                    if (ch.SubscriberCount != count) return "라운드 " + round + ", " + step + "번째 연산 뒤 SubscriberCount 기대 " + count + ", 결과 " + ch.SubscriberCount;
                    if (log.ToString() != expected.ToString()) return "라운드 " + round + ", " + step + "번째 연산 뒤 호출 로그가 참조 구현과 다름 (구독 번호 순서, ';' 는 Publish 경계)";
                }
            }
            return null;
        });
    }
}
